const input = $input.first().json;
const payload = input.body && typeof input.body === 'object' ? input.body : input;
const repository = 'nario0715masa0619-create/luvira-ai-devflow';
const owner = typeof payload.owner === 'string' ? payload.owner.trim() : '';
const slug = typeof payload.slug === 'string' ? payload.slug.trim() : '';
const description = typeof payload.description === 'string' ? payload.description.trim() : '';
if (!/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(owner)) throw new Error('ORCA_PROJECT_OWNER_INVALID');
if (!/^[a-z][a-z0-9-]{2,62}$/.test(slug)) throw new Error('ORCA_PROJECT_SLUG_INVALID');
if (!description || description.length > 160) throw new Error('ORCA_PROJECT_DESCRIPTION_INVALID');
const projectId = `project-${slug}`;
const body = `### Project Owner\n\n${owner}\n\n### Project Slug\n\n${slug}\n\n### プロダクト概要\n\n${description}`;
return [{ json: { repository, project_id: projectId, title: `[Project Onboarding]: ${slug}`, issue_body: body } }];

const issue = $input.first().json;
const project = $('Validate and Build Project Issue').first().json;
if (!Number.isInteger(issue.number) || typeof issue.html_url !== 'string') throw new Error('ORCA_PROJECT_ISSUE_CREATE_INVALID');
return [{ json: { status: 'AWAITING_HUMAN_APPROVAL', project_id: project.project_id, issue_number: issue.number, issue_url: issue.html_url } }];
